(function(){if(!("IntersectionObserver"in window)){document.querySelectorAll(".reveal").forEach(function(e){e.classList.add("is-visible")});return}var i=new IntersectionObserver(function(e){e.forEach(function(r){r.isIntersecting&&(r.target.classList.add("is-visible"),i.unobserve(r.target))})},{threshold:.12,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll(".reveal").forEach(function(e){i.observe(e)})})();
